css:
body{font-family:TwitterChirp,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
[data-slot="button"]{border-radius:999px!important;font-weight:700;}
[data-slot="input"],[data-slot="select-trigger"]{border-radius:999px!important;}
[data-thread-item]{border-radius:999px!important;}
[data-slot="composer-host"]{border-radius:16px!important;border:1px solid var(--border)!important;box-shadow:none!important;}
[data-slot="composer-host"]:focus-within{border-color:#1D9BF0!important;box-shadow:inset 0 0 0 1px #1D9BF0!important;}
button.bg-message-action{border-radius:999px!important;}
[data-user-message-bubble]{border-radius:16px!important;}
.chat-markdown-codeblock{border-radius:12px!important;border:1px solid var(--border);}
.dark [data-slot="dialog-popup"],.dark [data-slot="popover-popup"],.dark [data-slot="menu-popup"]{border-radius:16px!important;border:none!important;box-shadow:rgba(255,255,255,.2) 0 0 15px,rgba(255,255,255,.15) 0 0 3px 1px!important;}
:root:not(.dark) [data-slot="dialog-popup"],:root:not(.dark) [data-slot="popover-popup"],:root:not(.dark) [data-slot="menu-popup"]{border-radius:16px!important;border:none!important;box-shadow:rgba(101,119,134,.2) 0 0 15px,rgba(101,119,134,.15) 0 0 3px 1px!important;}
[data-slot="tooltip-popup"]{border-radius:4px!important;}
button.bg-message-action:disabled{opacity:.5!important;}
.dark [data-slot="switch"][data-unchecked]{background:#3E4144!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#CFD9DE!important;box-shadow:none!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#1D9BF0!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:10px;height:10px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 20%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
